import copy, sys
import docx
from docx.opc.constants import RELATIONSHIP_TYPE as RT
from docx.text.paragraph import Paragraph

W = '{http://schemas.openxmlformats.org/wordprocessingml/2006/main}'
doc = docx.Document(sys.argv[1])
body = doc.element.body

# --- прибрати коментарі ---
for tag in ('commentRangeStart', 'commentRangeEnd'):
    for el in list(body.iter(W + tag)):
        el.getparent().remove(el)
for ref in list(body.iter(W + 'commentReference')):
    r = ref.getparent()
    r.getparent().remove(r)
part = doc.part
for rid, rel in list(part.rels.items()):
    if 'comments' in rel.reltype.lower():
        part.rels.pop(rid)

def par(start):
    hits = [p for p in doc.paragraphs if p.text.strip().startswith(start)]
    assert len(hits) == 1, (start, len(hits))
    return hits[0]

def set_text(p, text):
    runs = [r for r in p.runs if r.text]
    keep = runs[0]
    for r in p.runs:
        if r._r is not keep._r:
            r._r.getparent().remove(r._r)
    keep.text = text
    return p

def add_after(p, text):
    new = copy.deepcopy(p._p)
    p._p.addnext(new)
    return set_text(Paragraph(new, p._parent), text)

# --- преамбула: опечатка «3амовник» (цифра 3) ---
for p in doc.paragraphs:
    for r in p.runs:
        if '«3амовник»' in r.text:
            r.text = r.text.replace('«3амовник»', '«Замовник»')

